import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { get, put } from '@vercel/blob';
import { config } from '../config';

/**
 * Private file storage (ADR-10). Files never go in the database; callers keep only the object
 * key. Keys are generated by the server (never from user input) and look like
 * "certificates/<uuid>.pdf".
 */
export interface Storage {
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  /** Null when there is no object under this key. */
  get(key: string): Promise<Buffer | null>;
}

const KEY = /^[a-z0-9][a-z0-9/_.-]*$/;
function checkKey(key: string) {
  if (!KEY.test(key) || key.includes('..')) throw new Error('Invalid storage key');
}

/** Development and tests: files under STORAGE_LOCAL_DIR (git-ignored). */
function localStorage(root: string): Storage {
  const file = (key: string) => path.join(path.resolve(root), ...key.split('/'));
  return {
    async put(key, body) {
      checkKey(key);
      await mkdir(path.dirname(file(key)), { recursive: true });
      await writeFile(file(key), body);
    },
    async get(key) {
      checkKey(key);
      try {
        return await readFile(file(key));
      } catch (err) {
        if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
        throw err;
      }
    },
  };
}

/** Production: a private Vercel Blob store. Objects are only readable with the server token. */
function vercelBlobStorage(token: string): Storage {
  return {
    async put(key, body, contentType) {
      checkKey(key);
      await put(key, body, {
        access: 'private',
        contentType,
        addRandomSuffix: false,
        allowOverwrite: true,
        token,
      });
    },
    async get(key) {
      checkKey(key);
      const res = await get(key, { access: 'private', token, useCache: false });
      if (!res || res.statusCode !== 200) return null;
      return Buffer.from(await new Response(res.stream).arrayBuffer());
    },
  };
}

let instance: Storage | undefined;

export function storage(): Storage {
  if (!instance) {
    const env = config();
    instance =
      env.STORAGE_DRIVER === 'vercel-blob'
        ? vercelBlobStorage(env.BLOB_READ_WRITE_TOKEN!)
        : localStorage(env.STORAGE_LOCAL_DIR);
  }
  return instance;
}

/** Tests only: swap in a fake (for example one that fails, to test the retry path). */
export function setStorageForTests(s: Storage | undefined) {
  instance = s;
}
